draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.moveTo(0, H * 0.7 + 20 * Math.sin(t));
  ctx.lineTo(W, H * 0.7 + 20 * Math.sin(t + Math.PI));
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W / 2, H * 0.4, 50 + 10 * Math.cos(t), 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(0, H);
  ctx.lineTo(0, H * 0.7 + 20 * Math.sin(t));
  ctx.lineTo(W, H * 0.7 + 20 * Math.sin(t + Math.PI));
  ctx.lineTo(W, H);
  ctx.stroke();
  ctx.restore();
}
